typedef struct {
    void (*on_done)(void *ctx, int status, const char *data);
    void *ctx;
} callback_t;

static void io_completed(int status, const char *data) {
    callback_t cb = pending;        /* take the registration */
    pending = (callback_t){0};      /* exactly one completion */
    if (cb.on_done) cb.on_done(cb.ctx, status, data);
}
